# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use a safety-first finite-state controller with confirmation, hysteretic steering,
    and paced reacquisition scans to approach only a currently verified target.
    """
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    previous_action = memory.get("previous_action", "")
    scan_age = int(memory.get("scan_age", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["previous_action"] = action
        return action, confidence, memory

    # Safety is an unconditional gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        memory["state"] = "REACQUIRE" if (lost_steps > 0 or state in {
            "LOCKED", "APPROACH", "VERIFY", "REACQUIRE"
        }) else "SEARCH"

        # A short stationary hold prevents reacting to a single bad frame.
        if lost_steps <= 1:
            return emit("STOP", 0.92, memory["state"])

        # Keep each scan direction for several frames, reducing command chatter.
        scan_age += 1
        if scan_age >= 3:
            scan_direction = (
                "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
            )
            scan_age = 0
        memory["scan_direction"] = scan_direction
        memory["scan_age"] = scan_age
        return emit(scan_direction, 0.74, "REACQUIRE")

    memory["scan_age"] = 0

    # Confirm a newly acquired identity before making progress.
    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 12.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")

        if bearing < -8.0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.87, "APPROACH")
        if bearing > 8.0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.87, "APPROACH")
        if observation["corridor_center"]:
            return emit("FORWARD", 0.84, "APPROACH")
        return emit("STOP", 0.98, "STOPPED")

    # A small deadband and turn hysteresis avoid needless left/right oscillation.
    turn_threshold = 10.0
    if previous_action == "VEER_LEFT" and bearing < -5.0:
        turn_threshold = 5.0
    elif previous_action == "VEER_RIGHT" and bearing > 5.0:
        turn_threshold = 5.0

    if bearing <= -turn_threshold:
        if observation["corridor_left"]:
            return emit("VEER_LEFT", 0.89, "APPROACH")
        return emit("STOP", 0.97, "STOPPED")

    if bearing >= turn_threshold:
        if observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.89, "APPROACH")
        return emit("STOP", 0.97, "STOPPED")

    if observation["corridor_center"]:
        return emit("FORWARD", 0.91, "APPROACH")

    # Do not advance without a safe corridor aligned with the target.
    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
